sys_script_include.script:
var LocationCheck = Class.create();
LocationCheck.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    isPublic: function() {
        return true;
    },
    isLocationAvailable: function() {
        var location = this.getParameter('sysparm_location');
        var date = this.getParameter('sysparm_date');

        var gr = new GlideRecord('x_1790229_event_ma_event_record ');
        gr.addQuery('u_location', location);
        gr.addQuery('u_event_date', date);
        gr.query();

        if (gr.next()) {
            return false;
        }
        return true;
    },

    type: 'LocationCheck'
});
